using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = "math", Name = "Mathematics", Description = "Pure and applied mathematics, from abstract algebra to statistics." },
            new() { Id = "eng", Name = "English", Description = "Literature, composition, and creative writing." },
            new() { Id = "phys", Name = "Physics", Description = "Fundamental principles governing matter, energy, and the universe." },
            new() { Id = "hist", Name = "History", Description = "Exploration of past civilizations, events, and cultural movements." },
            new() { Id = "bio", Name = "Biology", Description = "The science of life, from molecular genetics to ecology." },
        };

        _courses = new List<Course>
        {
            new()
            {
                Id = "CS101", Title = "Introduction to Computer Science", DepartmentId = "cs", DepartmentName = "Computer Science",
                Description = "A broad introduction to computer science covering computational thinking, basic programming in Python, data representation, and an overview of how computers work. No prior experience required.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 110",
                Instructor = new() { Name = "Dr. Ada Lovelace", Title = "Associate Professor", Bio = "Dr. Lovelace specializes in programming language theory and CS education. She has 12 years of teaching experience and has published extensively on introductory CS pedagogy.", Email = "alovelace@university.edu" },
                IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 87
            },
            new()
            {
                Id = "CS301", Title = "Data Structures and Algorithms", DepartmentId = "cs", DepartmentName = "Computer Science",
                Description = "In-depth study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms). Includes complexity analysis.",
                Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Location = "Science Hall 205",
                Instructor = new() { Name = "Dr. Alan Turing", Title = "Professor", Bio = "Dr. Turing's research focuses on computational complexity and algorithm optimization. He is the author of three textbooks on algorithms.", Email = "aturing@university.edu" },
                IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 55
            },
            new()
            {
                Id = "CS450", Title = "Machine Learning", DepartmentId = "cs", DepartmentName = "Computer Science",
                Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and model evaluation. Hands-on projects using real-world datasets.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Tech Building 301",
                Instructor = new() { Name = "Dr. Grace Hopper", Title = "Professor", Bio = "Dr. Hopper is an expert in AI and machine learning with over 50 published papers. She previously worked at a leading AI research lab.", Email = "ghopper@university.edu" },
                IsFeatured = true, MaxEnrollment = 45, CurrentEnrollment = 42
            },
            new()
            {
                Id = "MATH201", Title = "Linear Algebra", DepartmentId = "math", DepartmentName = "Mathematics",
                Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and inner product spaces. Essential for students in mathematics, physics, engineering, and computer science.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Building 102",
                Instructor = new() { Name = "Dr. Emmy Noether", Title = "Professor", Bio = "Dr. Noether is a renowned algebraist whose work bridges abstract algebra and applied linear algebra. She has mentored over 30 graduate students.", Email = "enoether@university.edu" },
                IsFeatured = true, MaxEnrollment = 80, CurrentEnrollment = 62
            },
            new()
            {
                Id = "MATH310", Title = "Probability and Statistics", DepartmentId = "math", DepartmentName = "Mathematics",
                Description = "Probability theory, random variables, distributions, hypothesis testing, regression analysis, and Bayesian inference. Applications drawn from science, engineering, and social sciences.",
                Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Math Building 205",
                Instructor = new() { Name = "Dr. Carl Gauss", Title = "Associate Professor", Bio = "Dr. Gauss specializes in statistical theory and its applications in data science. He consults for several Fortune 500 companies on analytics.", Email = "cgauss@university.edu" },
                IsFeatured = false, MaxEnrollment = 70, CurrentEnrollment = 48
            },
            new()
            {
                Id = "ENG101", Title = "Composition and Rhetoric", DepartmentId = "eng", DepartmentName = "English",
                Description = "Develops clear, effective writing skills through essay composition, rhetorical analysis, and revision workshops. Emphasizes argumentative and expository writing.",
                Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Humanities 310",
                Instructor = new() { Name = "Prof. Maya Angelou", Title = "Senior Lecturer", Bio = "Prof. Angelou is a published author and writing instructor with 20 years of experience teaching composition at the university level.", Email = "mangelou@university.edu" },
                IsFeatured = false, MaxEnrollment = 30, CurrentEnrollment = 28
            },
            new()
            {
                Id = "ENG350", Title = "Shakespeare and Early Modern Drama", DepartmentId = "eng", DepartmentName = "English",
                Description = "Close reading of Shakespeare's major plays and selected works by his contemporaries. Topics include performance history, gender, politics, and adaptation.",
                Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", Location = "Humanities 215",
                Instructor = new() { Name = "Dr. Virginia Woolf", Title = "Professor", Bio = "Dr. Woolf is a leading scholar of early modern English literature with a focus on Shakespeare's tragedies and their modern adaptations.", Email = "vwoolf@university.edu" },
                IsFeatured = true, MaxEnrollment = 35, CurrentEnrollment = 20
            },
            new()
            {
                Id = "PHYS201", Title = "Classical Mechanics", DepartmentId = "phys", DepartmentName = "Physics",
                Description = "Newtonian mechanics, Lagrangian and Hamiltonian formulations, oscillations, central force problems, and rigid body dynamics.",
                Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Location = "Physics Building 101",
                Instructor = new() { Name = "Dr. Richard Feynman", Title = "Professor", Bio = "Dr. Feynman is an award-winning physicist and educator known for making complex physics concepts accessible. He is a recipient of the university's Distinguished Teaching Award.", Email = "rfeynman@university.edu" },
                IsFeatured = false, MaxEnrollment = 50, CurrentEnrollment = 38
            },
            new()
            {
                Id = "HIST101", Title = "World History to 1500", DepartmentId = "hist", DepartmentName = "History",
                Description = "Survey of major civilizations from antiquity through the late medieval period, covering Mesopotamia, Egypt, Greece, Rome, China, the Islamic world, and medieval Europe.",
                Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Location = "Liberal Arts 401",
                Instructor = new() { Name = "Dr. Howard Zinn", Title = "Associate Professor", Bio = "Dr. Zinn specializes in social history and emphasizes the perspectives of ordinary people in historical narratives.", Email = "hzinn@university.edu" },
                IsFeatured = false, MaxEnrollment = 90, CurrentEnrollment = 72
            },
            new()
            {
                Id = "BIO101", Title = "General Biology", DepartmentId = "bio", DepartmentName = "Biology",
                Description = "Introduction to biological principles including cell biology, genetics, evolution, ecology, and organismal diversity. Includes weekly lab sessions.",
                Credits = 4, Schedule = "Mon/Wed 10:00–10:50 AM, Fri Lab 1:00–3:50 PM", Location = "Life Sciences 120",
                Instructor = new() { Name = "Dr. Jane Goodall", Title = "Professor", Bio = "Dr. Goodall is a primatologist and conservationist who brings field research experience into the classroom. She leads the university's biodiversity research initiative.", Email = "jgoodall@university.edu" },
                IsFeatured = true, MaxEnrollment = 100, CurrentEnrollment = 78
            },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string id) =>
        _departments.FirstOrDefault(d => d.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetCourses(string? search = null, string? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
        {
            query = query.Where(c => c.DepartmentId.Equals(departmentId, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Id.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.OrderBy(c => c.DepartmentId).ThenBy(c => c.Id).ToList();
    }

    public Course? GetCourse(string id) =>
        _courses.FirstOrDefault(c => c.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public void SubmitEnrollment(EnrollmentRequest request) =>
        _enrollments.Add(request);
}

