 @page "/enroll"
 @inject UniversityCourseCatalog.Services.CatalogService CatalogService

 <PageTitle>Enrollment Request</PageTitle>

 <h1>Submit Enrollment Request</h1>

 @if (submitted)
 {
     <div class="alert alert-success mt-3">
         <h4 class="alert-heading">Request Submitted!</h4>
         <p>
             Thank you, <strong>@Model.StudentName</strong> (ID: @Model.StudentId).
             Your enrollment request for <strong>@Model.CourseId</strong> has been received.
             You will receive a confirmation via your university email.
         </p>
         <hr />
         <a href="courses" class="btn btn-outline-success">Browse More Courses</a>
         <a href="enroll" class="btn btn-outline-primary ms-2">Submit Another Request</a>
     </div>
 }
 else
 {
     <p>Fill out the form below to request enrollment in a course.</p>

     <form method="post" @formname="enrollment" @onsubmit="HandleSubmit" class="mt-3" style="max-width: 600px;">
         <AntiforgeryToken />

         <div class="mb-3">
             <label for="studentName" class="form-label">Full Name</label>
             <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName"
                    class="form-control" required />
         </div>

         <div class="mb-3">
             <label for="studentId" class="form-label">Student ID</label>
             <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId"
                    class="form-control" required placeholder="e.g. S12345678" />
         </div>

         <div class="mb-3">
             <label for="courseId" class="form-label">Course</label>
             <select id="courseId" name="Model.CourseId" class="form-select" required>
                 <option value="">— Select a course —</option>
                 @foreach (var course in CatalogService.GetCourses())
                 {
                     <option value="@course.Id" selected="@(Model.CourseId == course.Id)">
                         @course.Id: @course.Title (@course.Credits cr)
                     </option>
                 }
             </select>
         </div>

         <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
         <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
     </form>
 }

 @code {
     [SupplyParameterFromForm]
     public EnrollmentRequest? Model { get; set; }

     protected override void OnInitialized()
     {
         Model ??= new();
         if (!string.IsNullOrEmpty(PreselectedCourse) && string.IsNullOrEmpty(Model.CourseId))
         {
             Model.CourseId = PreselectedCourse;
         }
     }

     [SupplyParameterFromQuery(Name = "course")]
     public string? PreselectedCourse { get; set; }

     private bool submitted;

     private void HandleSubmit()
     {
         CatalogService.SubmitEnrollment(Model);
         submitted = true;
     }
 }

